     if(q.kit.indexOf('scrap')>=0||q.kit.indexOf('wire')>=0) bad.push('FOUR: salvage was packed');
     if(q.stash.indexOf('medkit')<0) bad.push('FOUR: the kit took items out of the stash before the raid');
